#!/usr/bin/env python3
"""Draws the flat SVG illustrations in public/img/adjectives (original artwork for this project).
Run once: python3 scripts/draw-adjective-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'adjectives'
OUT.mkdir(parents=True, exist_ok=True)

BG = lambda c: f'<rect width="64" height="64" rx="8" fill="{c}"/>'
FACE = lambda x, y, mouth, shirt='#4d96ff', skin='#f5c6a5': (
    f'<circle cx="{x}" cy="{y}" r="7" fill="{skin}"/><path d="M{x - 7} {y - 2} Q{x} {y - 11} {x + 7} {y - 2}" fill="#5a2d1a"/>'
    f'<circle cx="{x - 2.5}" cy="{y - 1}" r="1" fill="#222"/><circle cx="{x + 2.5}" cy="{y - 1}" r="1" fill="#222"/>{mouth}'
    f'<rect x="{x - 8}" y="{y + 7}" width="16" height="16" rx="4" fill="{shirt}"/>')
SMILE = lambda x, y: f'<path d="M{x - 3} {y + 2.5} Q{x} {y + 5.5} {x + 3} {y + 2.5}" stroke="#222" stroke-width="1.2" fill="none"/>'
FROWN = lambda x, y: f'<path d="M{x - 3} {y + 4.5} Q{x} {y + 1.5} {x + 3} {y + 4.5}" stroke="#222" stroke-width="1.2" fill="none"/>'
NOTE = lambda x, y, c='#222': f'<circle cx="{x}" cy="{y}" r="3" fill="{c}"/><rect x="{x + 2}" y="{y - 12}" width="2" height="12" fill="{c}"/><path d="M{x + 4} {y - 12} Q{x + 10} {y - 10} {x + 8} {y - 5}" stroke="{c}" stroke-width="2" fill="none"/>'
BOOK = '<rect x="40" y="40" width="16" height="12" rx="1" fill="#fff" stroke="#8d5524"/><line x1="48" y1="40" x2="48" y2="52" stroke="#8d5524"/>'
SHIRT = lambda c, marks='': f'<path d="M14 18 L24 12 L32 16 L40 12 L50 18 L46 26 L42 24 L42 52 L22 52 L22 24 L18 26Z" fill="{c}" stroke="#555"/>' + marks

ICONS = {
    'cold': BG('#cfe8ff') + '<rect x="0" y="46" width="64" height="18" fill="#fff"/><circle cx="32" cy="40" r="12" fill="#fff" stroke="#ccc"/><circle cx="32" cy="22" r="8" fill="#fff" stroke="#ccc"/><circle cx="29" cy="20" r="1" fill="#222"/><circle cx="35" cy="20" r="1" fill="#222"/><path d="M32 22 L36 24 L32 25Z" fill="#ff8f00"/><rect x="26" y="10" width="12" height="6" fill="#222"/><rect x="24" y="15" width="16" height="2" fill="#222"/><path d="M20 38 L10 34 M44 38 L54 34" stroke="#8d5524" stroke-width="2"/><rect x="24" y="30" width="16" height="4" fill="#e63946"/>' + ''.join(f'<circle cx="{x}" cy="{y}" r="1.5" fill="#fff"/>' for x, y in [(8, 8), (16, 20), (52, 10), (58, 26), (10, 28), (50, 44)]),
    'hot': BG('#ffe08a') + '<circle cx="50" cy="12" r="8" fill="#ff8f00"/>' + ''.join(f'<line x1="50" y1="12" x2="{50 + 13 * dx}" y2="{12 + 13 * dy}" stroke="#ff8f00" stroke-width="2"/>' for dx, dy in [(-1, 0), (0, 1), (-.7, .7), (-.7, -.7), (0, -1), (.7, .7), (1, 0), (.7, -.7)]) + '<rect x="0" y="46" width="64" height="18" fill="#4d96ff"/><rect x="0" y="40" width="64" height="8" fill="#f4d58d"/><path d="M14 14 L14 42" stroke="#8d5524" stroke-width="2"/><path d="M14 14 Q0 22 14 30 Q28 22 14 14Z" fill="#e63946"/><path d="M14 14 Q6 22 14 30" fill="#fff"/>',
    'clean': BG('#e8f5e9') + SHIRT('#fff') + '<circle cx="48" cy="10" r="2" fill="#4caf50"/><path d="M6 8 L8 12 L12 12 L9 14 L10 18 L6 15 L2 18 L3 14 L0 12 L4 12Z" fill="#ffd54a" transform="translate(48 6) scale(.8)"/><path d="M6 8 L8 12 L12 12 L9 14 L10 18 L6 15 L2 18 L3 14 L0 12 L4 12Z" fill="#ffd54a" transform="translate(4 30) scale(.7)"/>',
    'dirty': BG('#efebe9') + SHIRT('#e0dcd6', '<ellipse cx="30" cy="34" rx="5" ry="4" fill="#5d4037"/><ellipse cx="38" cy="44" rx="4" ry="3" fill="#5d4037"/><circle cx="26" cy="46" r="2.5" fill="#8d6e63"/><circle cx="36" cy="26" r="2" fill="#5d4037"/>') + '<path d="M50 30 Q54 22 58 30" stroke="#999" stroke-width="1.5" fill="none"/><circle cx="52" cy="24" r="1.5" fill="#333"/>',
    'fast': BG('#fff8e1') + '<rect x="0" y="46" width="64" height="18" fill="#c8a165"/><ellipse cx="34" cy="36" rx="16" ry="8" fill="#e6a23c"/><circle cx="52" cy="30" r="6" fill="#e6a23c"/><path d="M18 36 Q6 30 4 40" stroke="#e6a23c" stroke-width="4" fill="none"/>' + ''.join(f'<circle cx="{x}" cy="{y}" r="1.5" fill="#5a2d1a"/>' for x, y in [(28, 34), (36, 38), (40, 32), (32, 40), (44, 38)]) + '<path d="M24 44 L18 52 M32 44 L28 52 M40 44 L44 52 M46 42 L52 50" stroke="#e6a23c" stroke-width="3" stroke-linecap="round"/><path d="M2 20 L14 20 M4 26 L12 26 M6 14 L16 14" stroke="#999" stroke-width="2" stroke-linecap="round"/>',
    'slow': BG('#e8f5e9') + '<rect x="0" y="46" width="64" height="18" fill="#7cb342"/><ellipse cx="30" cy="38" rx="18" ry="12" fill="#2e7d32"/>' + ''.join(f'<path d="M{x} {y} l6 -4 l6 4 l-6 4Z" fill="#4caf50"/>' for x, y in [(16, 36), (26, 30), (36, 34), (26, 42)]) + '<rect x="12" y="44" width="36" height="6" fill="#1b5e20"/><ellipse cx="52" cy="42" rx="6" ry="5" fill="#8bc34a"/><circle cx="54" cy="41" r="1" fill="#222"/><path d="M4 30 Q8 26 6 22" stroke="#999" stroke-width="1.5" fill="none"/>',
    'friendly': BG('#fff3e0') + FACE(22, 22, SMILE(22, 22), '#4d96ff') + FACE(44, 22, SMILE(44, 22), '#e63946', '#c68642') + '<path d="M30 36 L36 36" stroke="#f5c6a5" stroke-width="4" stroke-linecap="round"/><path d="M8 10 Q12 4 16 10" stroke="#e63946" stroke-width="2" fill="none"/><path d="M48 8 Q52 2 56 8" stroke="#e63946" stroke-width="2" fill="none"/>',
    'unfriendly': BG('#eceff1') + FACE(20, 22, FROWN(20, 22), '#607d8b') + FACE(46, 22, FROWN(46, 22), '#795548', '#c68642') + '<path d="M17 17 L23 18 M43 18 L49 17" stroke="#222" stroke-width="1.5"/><line x1="33" y1="8" x2="33" y2="50" stroke="#999" stroke-width="2" stroke-dasharray="3 3"/>',
    'nice': BG('#fce4ec') + '<rect x="24" y="36" width="16" height="18" rx="3" fill="#4d96ff"/><path d="M32 36 L32 20" stroke="#4caf50" stroke-width="2"/>' + ''.join(f'<circle cx="{x}" cy="{y}" r="5" fill="{c}"/><circle cx="{x}" cy="{y}" r="2" fill="#ffd54a"/>' for x, y, c in [(22, 20, '#e63946'), (32, 14, '#ff8f00'), (42, 20, '#9c27b0'), (27, 27, '#ff6ec7'), (37, 27, '#e63946')]) + '<path d="M50 34 Q54 28 58 34 Q54 40 50 34Z" fill="#e63946"/>',
    'horrible': BG('#d7ccc8') + '<path d="M18 30 L46 30 L44 56 L20 56Z" fill="#78909c"/><ellipse cx="32" cy="30" rx="14" ry="3" fill="#546e7a"/><path d="M24 30 L26 22 L30 26 L32 18 L36 26 L40 22 L40 30" fill="#8d6e63"/><path d="M26 18 Q28 10 24 6 M34 14 Q36 6 32 2 M40 18 Q44 12 40 6" stroke="#999" stroke-width="1.5" fill="none"/><ellipse cx="14" cy="14" rx="3" ry="2" fill="#333"/><ellipse cx="52" cy="10" rx="2.5" ry="1.5" fill="#333"/>',
    'large': BG('#e3f2fd') + '<rect x="0" y="50" width="64" height="14" fill="#8d5524"/><path d="M10 14 L10 50 L46 50 L46 14Z" fill="#fff" stroke="#999"/><path d="M46 22 Q58 22 58 32 Q58 42 46 42" stroke="#999" stroke-width="3" fill="none"/><rect x="10" y="12" width="36" height="4" rx="1" fill="#fff" stroke="#999"/>',
    'small': BG('#e3f2fd') + '<rect x="0" y="50" width="64" height="14" fill="#8d5524"/><path d="M26 36 L26 50 L40 50 L40 36Z" fill="#fff" stroke="#999"/><path d="M40 40 Q46 40 46 43 Q46 46 40 46" stroke="#999" stroke-width="2" fill="none"/><rect x="26" y="35" width="14" height="2" fill="#fff" stroke="#999"/>',
    'long': BG('#fffde7') + '<rect x="4" y="30" width="56" height="5" fill="#e63946" transform="rotate(-20 32 32)"/><path d="M4 30 L0 32.5 L4 35Z" fill="#f5c6a5" transform="rotate(-20 32 32)"/><rect x="56" y="30" width="4" height="5" fill="#333" transform="rotate(-20 32 32)"/>',
    'short': BG('#fffde7') + '<rect x="24" y="30" width="18" height="5" fill="#e63946" transform="rotate(-20 32 32)"/><path d="M24 30 L20 32.5 L24 35Z" fill="#f5c6a5" transform="rotate(-20 32 32)"/><rect x="40" y="30" width="3" height="5" fill="#333" transform="rotate(-20 32 32)"/>',
    'noisy': BG('#ede7f6') + '<rect x="4" y="30" width="20" height="26" rx="2" fill="#222"/><circle cx="14" cy="42" r="7" fill="#555"/><circle cx="14" cy="42" r="3" fill="#999"/>' + FACE(44, 22, '<ellipse cx="44" cy="25" rx="2" ry="3" fill="#222"/>', '#9c27b0') + '<path d="M38 12 L36 6 L34 14" stroke="#8d5524" stroke-width="3" fill="none"/>' + NOTE(30, 16, '#e63946') + NOTE(54, 12, '#4d96ff') + '<path d="M26 34 Q30 40 26 46 M30 30 Q36 40 30 50" stroke="#999" stroke-width="1.5" fill="none"/>',
    'quiet': BG('#e8eaf6') + '<rect x="0" y="48" width="64" height="16" fill="#8d5524"/>' + FACE(28, 24, '<line x1="25" y1="27" x2="31" y2="27" stroke="#222" stroke-width="1.2"/>', '#4caf50') + '<path d="M14 40 L26 44 L38 40 L38 48 L26 52 L14 48Z" fill="#fff" stroke="#8d5524"/><line x1="26" y1="44" x2="26" y2="52" stroke="#8d5524"/><text x="46" y="20" font-family="sans-serif" font-size="9" fill="#5c6bc0">Shh</text><rect x="48" y="30" width="8" height="18" fill="#fff" stroke="#ccc"/><line x1="48" y1="36" x2="56" y2="36" stroke="#ccc"/>',
}

for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">{body}</svg>'
    (OUT / f'{name}.svg').write_text(svg)
print(f'wrote {len(ICONS)} icons to {OUT}')
